for (const mode of ['local','remote']) {
  test(`${mode}: published owned bytes survive engine crash`,async t=>{
    const os=require('node:os'), {fork}=require('node:child_process');
    const dir=await fs.mkdtemp(path.join(os.tmpdir(),'publication-crash-')); await fs.mkdir(path.join(dir,'root'));
    t.after(()=>fs.rm(dir,{recursive:true,force:true}));
    const child=fork(path.join(__dirname,'helpers','publication-child.cjs'),[dir,mode],{stdio:['ignore','ignore','ignore','ipc']});
    await new Promise((resolve,reject)=>{child.on('message',m=>m==='published'?resolve():reject(Error(JSON.stringify(m))));child.on('exit',c=>reject(Error('child exited '+c)));});
    child.kill(); await new Promise(r=>child.once('exit',r));
    const {start}=require('./helpers/publication-child.cjs'); const x=await start(dir,mode);
    t.after(async()=>{if(x.server){await x.client.close();await x.server.close();}await x.engine.close();});
    const jobs=(await x.client.getSnapshot()).jobs; assert.equal(jobs.length,1); assert.equal(jobs[0].status,'completed'); assert.equal(jobs[0].verification,'verified'); assert.equal(await fs.readFile(path.join(dir,'root','file.bin'),'utf8'),'data');
  });
}
