for (const mode of ['local','remote']) {
 for (const swap of ['root junction','partial replacement']) test(`${mode}: mismatch cleanup preserves foreign file after ${swap}`,async t=>{
  const f=await withEngine(t,mode,{file:{size:4},bytes:'data'}); const original=fs.lstat; let changed=false, foreign;
  fs.lstat=async function(input,...args) {
   if(!changed && path.dirname(String(input)).toLowerCase()===f.root.toLowerCase() && String(input).endsWith('.download')) {
    changed=true;
    if(swap==='root junction') { const outside=path.join(f.dir,'outside'); await fs.mkdir(outside); foreign=path.join(outside,path.basename(String(input))); await fs.writeFile(foreign,'foreign'); await fs.rename(f.root,f.root+'-original'); await fs.symlink(outside,f.root,'junction'); }
    else { foreign=String(input); await fs.rename(foreign,foreign+'.owned'); await fs.writeFile(foreign,'foreign'); }
   }
   return original.call(this,input,...args);
  };
  t.after(()=>{fs.lstat=original}); await f.client.execute('downloadFile',['1',{deleteAfterDownload:true}]); const job=await terminal(f.client);
  assert.equal(changed,true); assert.equal(job.status,'needs-attention'); assert.equal(await fs.readFile(foreign,'utf8').catch(e=>e.code),'foreign'); assert.deepEqual(f.deleted,[]);
 });
}

for (const mode of ['local','remote']) for (const phase of ['prepared','cleaning']) test(`${mode}: ${phase} notification save failure blocks source deletion`,async t=>{
 const f=await withEngine(t,mode,{file:{size:4},bytes:'data'}); const original=fs.rename; let rejected=false;
 fs.rename=async(from,to)=>{ if(!rejected && String(to).endsWith('engine.json')) { const state=JSON.parse(await fs.readFile(from,'utf8')); const match=phase==='prepared' ? Object.values(state.recovery||{}).some(r=>r.finalization?.phase==='prepared') : state.jobs.some(j=>j.status==='cleaning'); if(match){rejected=true;throw Object.assign(Error('fixture save failure'),{code:'EIO'});} } return original(from,to); };
 t.after(()=>{fs.rename=original}); await f.client.execute('downloadFile',['1',{deleteAfterDownload:true}]); const job=await terminal(f.client); assert.equal(rejected,true); assert.equal(job.status,phase==='prepared'?'needs-attention':'completed'); if(phase==='cleaning'){assert.equal(job.verification,'verified');assert.equal(job.cleanupStatus,'not-started');assert.ok(job.cleanupWarning);assert.equal(job.error,undefined);} assert.deepEqual(f.deleted,[]);
 if(phase==='prepared') await assert.rejects(fs.lstat(path.join(f.root,'file.bin')),{code:'ENOENT'}); else assert.equal(await fs.readFile(path.join(f.root,'file.bin'),'utf8'),'data');
});
