for (const mode of ['local','remote']) test(`${mode}: cancel during retry persistence never dispatches the stale wake`,async t=>{
 const runtime=controlledRuntime();let attempts=0,blocked=false,release;const gate=new Promise(r=>release=r);const f=await withEngine(t,mode,{downloadRuntime:runtime,file:{size:4},response:()=>{attempts++;return new Response('',{status:503});}});await f.client.execute('downloadFile',['1']);const job=await waiting(f.client);
 const rename=fs.rename;fs.rename=async(from,to)=>{if(!blocked && String(to).endsWith('engine.json')){const state=JSON.parse(await fs.readFile(from,'utf8'));if(state.jobs.some(j=>j.id===job.id&&j.status==='queued')){blocked=true;await gate;}}return rename(from,to);};t.after(()=>{fs.rename=rename;release()});const armEnd=Date.now()+3000;while(runtime.nextDeadline()!==Date.parse(job.retryAt)&&Date.now()<armEnd)await new Promise(r=>setTimeout(r,10));assert.equal(runtime.nextDeadline(),Date.parse(job.retryAt));runtime.advance(1000);const end=Date.now()+3000;while(!blocked&&Date.now()<end)await new Promise(r=>setTimeout(r,10));assert.equal(blocked,true);const cancel=f.client.execute('cancelDownloads',[[job.id]]);await new Promise(r=>setTimeout(r,30));release();await cancel;runtime.advance(60000);await new Promise(r=>setTimeout(r,30));assert.equal((await f.client.getSnapshot()).jobs[0].status,'canceled');assert.equal(attempts,1);
});
for (const mode of ['local','remote']) test(`${mode}: retry state save failure requires attention and sends no new request`,async t=>{
 const runtime=controlledRuntime();let attempts=0,failed=false;const f=await withEngine(t,mode,{downloadRuntime:runtime,file:{size:4},response:()=>{attempts++;return new Response('',{status:503});}});await f.client.execute('downloadFile',['1']);const job=await waiting(f.client);
 const rename=fs.rename;fs.rename=async(from,to)=>{if(!failed && String(to).endsWith('engine.json')){const state=JSON.parse(await fs.readFile(from,'utf8'));if(state.jobs.some(j=>j.id===job.id&&j.status==='queued')){failed=true;throw Object.assign(new Error('fixture'),{code:'EIO'});}}return rename(from,to);};t.after(()=>{fs.rename=rename});const armEnd=Date.now()+3000;while(runtime.nextDeadline()!==Date.parse(job.retryAt)&&Date.now()<armEnd)await new Promise(r=>setTimeout(r,10));assert.equal(runtime.nextDeadline(),Date.parse(job.retryAt));runtime.advance(1000);let current;const end=Date.now()+3000;while(Date.now()<end){current=(await f.client.getSnapshot()).jobs[0];if(current.status==='needs-attention')break;await new Promise(r=>setTimeout(r,10));}assert.equal(current.status,'needs-attention');assert.equal(attempts,1);
});
